package dev.sablelife.testing;
import dev.sablelife.SableLife;
import dev.sablelife.heart.*;
import dev.sablelife.module.*;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.animal.Pig;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.gametest.*;
import java.util.List;
@GameTestHolder("sablelife_blast_tests") @PrefixGameTestTemplate(false)
public final class SphereBlastGameTests {
    private static HeartBlockEntity fixture(GameTestHelper h){var level=h.getLevel();var p=h.absolutePos(new BlockPos(3,6,3));level.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());level.setBlockAndUpdate(p.east(),Blocks.IRON_BLOCK.defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(level,p,List.of(p,p.east()),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+1,p.getY(),p.getZ()));return (HeartBlockEntity)level.getBlockEntity(b.getPlot().getCenterBlock());}
    private static VirtualModule module(HeartBlockEntity core){var m=core.modules().add("sphere_blast");m.anchors(List.of(ModuleAnchor.create(core,core.getBlockPos(),Direction.UP)));return m;}
    private static Pig pig(GameTestHelper h,Vec3 p){var e=EntityType.PIG.create(h.getLevel());e.setPos(p.x,p.y,p.z);e.setNoAi(true);e.setNoGravity(true);h.getLevel().addFreshEntity(e);return e;}
    @GameTest(template="combat",batch="sphere_config") public static void GeometryAndStageSelectionsSurviveReload(GameTestHelper h){
        var core=fixture(h);var m=module(core);var a=ModuleSphereBlast.center(core,m);m.edit("startDistance",2,"");m.edit("sphereDistance",10,"");var b=ModuleSphereBlast.center(core,m);h.assertTrue(Math.abs(b.distanceTo(a)-4)<.0001,"Start and distance did not shift center");
        m.movementParticles("Charge").editParticle("add","minecraft:soul_fire_flame");m.movementParticles("Blast").editParticle("remove","minecraft:explosion");m.editEffect("add","minecraft:slowness",0);var copy=VirtualModule.load(m.save());
        h.assertTrue(copy.movementParticles("Charge").particles().contains("minecraft:soul_fire_flame")&&copy.movementParticles("Blast").particles().isEmpty()&&copy.effects().size()==1,"Independent stages/effects lost");h.assertTrue(copy.value("blastBlocks")==0&&MoveSet.TARGETS.contains(m.type())&&!RedstoneCorePolicy.allowed(m),"Defaults/core whitelist/Move set registration wrong");h.succeed();
    }
    @GameTest(template="combat",batch="sphere_damage") public static void SphericalDamageHitsOnceAndAppliesEffect(GameTestHelper h){
        var core=fixture(h);var m=module(core);m.edit("damage",3,"");m.edit("blastRadius",2,"");m.editEffect("add","minecraft:slowness",0);var p=ModuleSphereBlast.center(core,m);var inside=pig(h,p);var corner=pig(h,p.add(1.9,1.9,1.9));var terrain=BlockPos.containing(p).below();h.getLevel().setBlockAndUpdate(terrain,Blocks.GLASS.defaultBlockState());
        ModuleSphereBlast.detonate(h.getLevel(),core,m,p);h.assertTrue(inside.getHealth()==7&&inside.hasEffect(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN),"Blast damage/effect wrong or doubled");h.assertTrue(corner.getHealth()==10,"AABB corner outside sphere was hit");h.assertTrue(h.getLevel().getBlockState(terrain).is(Blocks.GLASS),"Off destroyed terrain");h.succeed();
    }
    @GameTest(template="combat",batch="sphere_blocks") public static void BlockToggleDestroysFragileTerrainWithoutDuplicateDamage(GameTestHelper h){var core=fixture(h);var m=module(core);m.edit("blastBlocks",1,"");m.edit("blastRadius",8,"");m.edit("damage",3,"");var p=ModuleSphereBlast.center(core,m);var block=BlockPos.containing(p);h.getLevel().setBlockAndUpdate(block,Blocks.GLASS.defaultBlockState());var target=pig(h,p.add(0,1,0));ModuleSphereBlast.detonate(h.getLevel(),core,m,p);h.assertTrue(!h.getLevel().getBlockState(block).is(Blocks.GLASS)&&target.getHealth()==7,"On failed destruction or duplicated damage");h.succeed();}
    @GameTest(template="combat",batch="sphere_charge",timeoutTicks=30) public static void ChargingDelaysDamageAndFreezesCast(GameTestHelper h){var core=fixture(h);var m=module(core);m.edit("chargeTime",8,"");m.edit("interval",100,"");m.edit("damage",3,"");var target=pig(h,ModuleSphereBlast.center(core,m));core.tryActivate(TestActors.creative(h.getLevel()));core.modules().tick(core);h.assertTrue(target.getHealth()==10,"Charging caused premature damage");m.edit("damage",9,"");h.runAfterDelay(12,()->{h.assertTrue(target.getHealth()==7,"Cast was not frozen or failed to explode once: HP="+target.getHealth());h.succeed();});}
    @GameTest(template="combat",batch="sphere_cancel",timeoutTicks=30) public static void MarkLossCancelsPendingBlast(GameTestHelper h){var core=fixture(h);var m=module(core);m.edit("chargeTime",8,"");var target=pig(h,ModuleSphereBlast.center(core,m));core.tryActivate(TestActors.creative(h.getLevel()));core.modules().tick(core);m.clearMarks();h.runAfterDelay(12,()->{h.assertTrue(target.getHealth()==10,"Mark loss did not cancel charging: HP="+target.getHealth());h.succeed();});}
    @GameTest(template="combat",batch="sphere_hurt",timeoutTicks=30) public static void HurtOnceKeepsSignalThroughChargeAndFiresOnce(GameTestHelper h){var core=fixture(h);var m=module(core);m.edit("trigger",5,"");m.edit("chargeTime",8,"");m.edit("damage",3,"");var target=pig(h,ModuleSphereBlast.center(core,m));core.tryActivate(TestActors.creative(h.getLevel()));core.damage(1);h.runAfterDelay(15,()->{h.assertTrue(target.getHealth()==7&&!core.modules().hurtTriggers.powered(m.id()),"Hurt Once cut short charging or repeated explosion");h.succeed();});}

    @GameTest(template="combat",batch="sphere_charge_motion") public static void ChargingTravelIsInwardAndSpeedControlsTicks(GameTestHelper h){var m=new VirtualModule("sphere_blast");h.assertTrue(m.movementParticles("Charge").particles().equals(List.of("minecraft:small_flame","minecraft:firework")),"Default charge selection incorrect");m.edit("sphereChargeSpeed",1,"");var center=new Vec3(12,4,-8);var packets=ModuleSphereBlast.chargeParticles(m,center,40);h.assertTrue(packets.size()==96,"Charge shell incomplete");for(var p:packets)h.assertTrue(Math.abs(p.from().distanceTo(center)-4)<1e-6&&p.to().distanceTo(center)<1e-6&&Math.abs(p.from().distanceTo(p.to())-4)<1e-6&&p.ticks()==80&&p.life()<=40,"Charge does not move to center");m.edit("sphereChargeSpeed",2,"");h.assertTrue(ModuleSphereBlast.chargeParticles(m,center,4).getFirst().ticks()==40&&ModuleSphereBlast.chargeParticles(m,center,4).getFirst().life()==4,"Speed/lifetime incorrect");m.edit("blastRadius",.5,"");for(var p:ModuleSphereBlast.chargeParticles(m,center,40))h.assertTrue(p.to().distanceTo(center)<1e-7,"Small sphere crossed center");h.assertTrue(ModuleSphereBlast.chargeParticles(m,center,0).isEmpty()&&VirtualModule.load(m.save()).value("sphereChargeSpeed")==2,"Zero charge/save failed");h.succeed();}
    @GameTest(template="combat",batch="sphere_burst_motion") public static void ExplosionParticlesExpandFromCenterToConfiguredRadiusAtFixedSpeed(GameTestHelper h){var m=new VirtualModule("sphere_blast");var center=new Vec3(-8,4,12);for(double radius:new double[]{.5,4,16})for(double speed:new double[]{.1,1,20}){m.edit("blastRadius",radius,"");m.edit("sphereChargeSpeed",speed,"");var packets=ModuleSphereBlast.burstParticles(m,center);var ids=packets.stream().map(ParticleTravelPacket::id).collect(java.util.stream.Collectors.toSet());h.assertTrue(ids.containsAll(List.of("minecraft:small_flame","minecraft:firework","minecraft:explosion")),"Selected charging/explosion stages not emitted");for(var p:packets)h.assertTrue(p.from().distanceTo(center)<1e-6&&Math.abs(p.to().distanceTo(center)-radius)<1e-6&&p.ticks()==Math.max(1,(int)Math.ceil(radius*20/12))&&p.life()>p.ticks(),"Burst did not expand from center to radius at fixed speed");}m.movementParticles("Charge").editParticle("remove","minecraft:small_flame");m.movementParticles("Charge").editParticle("remove","minecraft:firework");h.assertTrue(ModuleSphereBlast.burstParticles(m,center).stream().allMatch(p->p.id().equals("minecraft:explosion")),"Independent explosion selection was lost");m.movementParticles("Blast").editParticle("remove","minecraft:explosion");h.assertTrue(ModuleSphereBlast.burstParticles(m,center).isEmpty(),"Explicit empty stages unexpectedly burst");h.succeed();}

}
